function toggleTracebackView() {
  const tracebackArea = document.getElementById("traceback_area");
  const interactiveView = document.getElementById("interactive_view");
  const plaintextView = document.getElementById("plaintext_view");
  const copyButton = document.getElementById("copy_traceback_button");
