    viewToggle.textContent = "Plaintext view";
  } else {
    tracebackArea.style.display = "none";
    interactiveView.style.display = "none";
    plaintextView.style.display = "block";
    copyButton.style.display = "inline-block";
    viewToggle.textContent = "Interactive view";
  }
}

function copyTraceback() {
  const tracebackText = document.getElementById("traceback_textarea").value;
  navigator.clipboard.writeText(tracebackText).then(
    function() {
      // Optional: show a toast or change button text to indicate success
    },
    function(err) {
      console.error("Unable to copy traceback: ", err);
    }
  );
}

